insert into public.packages (title, slug, kind, destination, duration_days, price_usd, compare_at_price, summary, description, highlights, includes, departures, images, seats, is_featured) values
('Istanbul Student Week', 'istanbul-student-week', 'trip', 'Istanbul', 7, 549, 649, 'Seven days across Istanbul with the Bosphorus, old city and campus areas covered.', 'A full week built for students. Walk the old city, cross the Bosphorus by ferry, see Galata at sunset and spend evenings in student neighbourhoods. Groups stay small and everything is planned for you.', array['Hagia Sophia and the old city','Bosphorus ferry ride','Galata Tower at sunset','Grand Bazaar and local food'], array['Return flights from Cairo','Student-friendly hotel','Airport transfers','Local guide','Support in Arabic on WhatsApp'], array['2026-12-20','2027-01-10','2027-02-14'], array['https://images.unsplash.com/photo-1623621534850-d325a1980c7e?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1589561454226-796a8aa89b05?auto=format&fit=crop&w=1200&q=80'], 24, true),
('Cappadocia Balloon Escape', 'cappadocia-balloon-escape', 'trip', 'Cappadocia', 5, 429, null, 'Five days of valleys, cave hotels and sunrise balloons in central Turkey.', 'Fly to Kayseri, stay in a cave hotel and spend your mornings watching the balloons rise. Includes valley hikes and a day tour of the underground cities.', array['Sunrise over the balloons','Cave hotel stay','Valley hiking day','Underground city tour'], array['Return flights from Cairo','Student-friendly hotel','Airport transfers','Local guide','Support in Arabic on WhatsApp'], array['2026-12-27','2027-01-17'], array['https://images.unsplash.com/photo-1695415683093-ae5f213ea898?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1604156789095-3348604c0f43?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1627933577672-d191b77baa9c?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1565694286329-16c31ae20a20?auto=format&fit=crop&w=1200&q=80'], 18, true),
('Antalya Coast Break', 'antalya-coast-break', 'trip', 'Antalya', 6, 489, null, 'Six relaxed days on the Mediterranean coast with old town walks and beach time.', 'A calm break after exams. Stay near the old harbour, swim, take a boat day and explore the old town. Perfect for friends travelling together.', array['Old town and harbour','Boat day on the coast','Free beach days','Local seafood evenings'], array['Return flights from Cairo','Student-friendly hotel','Airport transfers','Local guide','Support in Arabic on WhatsApp'], array['2027-06-15','2027-07-05'], array['https://images.unsplash.com/photo-1582588677647-1a38fd18fd21?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1571942059435-b1ef2cf9b099?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1713885639308-d953cc619ffd?auto=format&fit=crop&w=1200&q=80'], 30, false),
('Istanbul and Cappadocia Combo', 'istanbul-cappadocia-combo', 'trip', 'Istanbul + Cappadocia', 10, 899, 1050, 'Ten days that join the two classics: the big city and the volcanic valleys.', 'Start in Istanbul with the old city and the Bosphorus, then fly inland to Cappadocia for the balloons and cave stays. The best value if you only travel once.', array['Istanbul old city and Bosphorus','Domestic flight to Cappadocia','Balloon sunrise','Cave hotel stay'], array['Return flights from Cairo','Student-friendly hotel','Airport transfers','Local guide','Support in Arabic on WhatsApp','Domestic flight included'], array['2026-12-22','2027-01-12'], array['https://images.unsplash.com/photo-1631152282084-b8f1b380ccab?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1636537511494-c3e558e0702b?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1623613229313-5e59f698526f?auto=format&fit=crop&w=1200&q=80'], 16, true),
('Winter Break in Istanbul', 'winter-break-istanbul', 'trip', 'Istanbul', 6, 519, null, 'Six winter days in Istanbul with museums, markets and warm cafes.', 'Skip the crowds and enjoy Istanbul in winter. Museums, covered markets, ferry rides and cozy cafes, with a hotel close to public transport.', array['Museum day','Spice and covered markets','Ferry along the Bosphorus','Winter city walks'], array['Return flights from Cairo','Student-friendly hotel','Airport transfers','Local guide','Support in Arabic on WhatsApp'], array['2027-01-24','2027-02-07'], array['https://images.unsplash.com/photo-1626956291772-3aa243614fd0?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1623439844752-524658b16ce6?auto=format&fit=crop&w=1200&q=80'], 22, false),
('Weekend City Break', 'weekend-city-break', 'trip', 'Istanbul', 3, 279, null, 'A short three day escape to see the highlights of Istanbul.', 'The fastest way to see Istanbul. Three days with the main sights, a Bosphorus cruise and free time to shop and eat.', array['Main sights in one day','Bosphorus views','Free evening','Easy airport transfers'], array['Return flights from Cairo','Hotel for two nights','Airport transfers','Support in Arabic on WhatsApp'], array['2027-03-05','2027-03-19'], array['https://images.unsplash.com/photo-1564428366891-dc20b1edf33b?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1567527259232-3a7fcd490c55?auto=format&fit=crop&w=1200&q=80'], 28, false),
('University Admission Support', 'university-admission-support', 'study', 'Istanbul', 7, 690, null, 'A guided week in Istanbul to visit campuses and prepare your admission.', 'Visit universities, meet admission offices, get help with documents and learn how student life works. A practical first step before you apply.', array['Campus visits','Admission office meetings','Document checklist','Student housing tips'], array['Return flights from Cairo','Hotel for the week','Campus visit transfers','Admission guidance','Support in Arabic on WhatsApp'], array['2027-02-21','2027-03-14'], array['https://images.unsplash.com/photo-1790098979193-1ab0a7e53f63?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1769543502300-23861c7d613f?auto=format&fit=crop&w=1200&q=80'], 12, true),
('Turkish Language Summer Course', 'turkish-language-summer', 'summer', 'Istanbul', 28, 1450, 1690, 'Four weeks of Turkish lessons in Istanbul with trips on the weekends.', 'Learn Turkish in the city where you use it. Morning lessons, afternoon activities and weekend trips. Suitable for beginners and for students planning to study in Turkey.', array['Morning Turkish lessons','Weekend city trips','Language practice with locals','Certificate of attendance'], array['Return flights from Cairo','Shared student accommodation','Course materials','Airport transfers','Support in Arabic on WhatsApp'], array['2027-07-04','2027-08-01'], array['https://images.unsplash.com/photo-1769498705048-eaee2bb3d198?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1564407727371-3eece6c58961?auto=format&fit=crop&w=1200&q=80'], 14, true)
